-- All mutations execute in a subtransaction that is deliberately rolled back.
-- Replace __TOKEN__ in memory only; never commit a real capability here.
create temporary table manager_test_result(report jsonb) on commit drop;
do $$
declare token text:='__TOKEN__';club uuid;other_club uuid;court uuid;dest uuid;rate uuid;peak uuid;promo uuid;res uuid;blk uuid;out jsonb;q jsonb;log jsonb:='[]';dt date;day_no int;st timestamptz;v boolean;
begin
 begin
 select id into club from public.clubs where slug='demo-bosque';
 select id into other_club from public.clubs where slug='demo-parque';
 dt:=(now() at time zone 'America/Santiago')::date+3;day_no:=extract(isodow from dt)::int-1;st:=(dt+time '17:30') at time zone 'America/Santiago';
 begin perform public.manager_gateway('invalid','court.save',club,'{}');raise exception 'Unauthorized write succeeded';exception when insufficient_privilege then null;end;
 log:=log||'"invalid capability denied"'::jsonb;
 out:=public.manager_gateway(token,'court.save',club,'{"name":"TEST court","court_number":901,"status":"ACTIVE","is_indoor":true}');court:=(out->>'id')::uuid;
 perform public.manager_gateway(token,'court.save',club,jsonb_build_object('court_id',court,'name','TEST court edited','court_number',901,'status','INACTIVE','is_indoor',true));
 assert(select name='TEST court edited' and status='INACTIVE' from public.courts where id=court);
 assert not exists(select 1 from public.court_availability(club,dt,30) where court_id=court);
 log:=log||'"create edit deactivate court and hide availability"'::jsonb;
 perform public.manager_gateway(token,'court.save',club,jsonb_build_object('court_id',court,'name','TEST court edited','court_number',901,'status','ACTIVE','is_indoor',true));
 perform public.manager_gateway(token,'hours.save',club,jsonb_build_object('court_id',court,'days',jsonb_build_array(day_no),'windows','[{"start_min":480,"end_min":780},{"start_min":900,"end_min":1500}]'::jsonb));
 assert(select count(*)=2 from public.court_operating_windows where court_id=court and weekday=day_no);
 assert exists(select 1 from private.operating_periods(court,dt+1) p where p @> ((dt+1+time '00:30') at time zone 'America/Santiago'));
 log:=log||'"multiple windows and overnight tail"'::jsonb;
 out:=public.manager_gateway(token,'rate.save',club,jsonb_build_object('alias','TEST base','amount',100,'currency','CLP','is_active',true,'is_default',true));rate:=(out->>'id')::uuid;
 out:=public.manager_gateway(token,'rate.save',club,jsonb_build_object('alias','TEST peak','amount',200,'currency','CLP','is_active',true,'is_default',false));peak:=(out->>'id')::uuid;
 perform public.manager_gateway(token,'schedule.apply',club,jsonb_build_object('court_ids',jsonb_build_array(court),'days',jsonb_build_array(day_no),'start_min',1080,'end_min',1380,'rate_plan_id',peak));
 q:=private.quote_court(court,st,90);assert(q->>'amount')::numeric=500;
 log:=log||'"default plus scheduled price sums three blocks"'::jsonb;
 out:=public.manager_gateway(token,'reservation.create',club,jsonb_build_object('court_id',court,'start_local',dt||'T17:30','minutes',90,'customer_label','Cliente Test Demo','status','CONFIRMED'));res:=(out->>'id')::uuid;
 assert(select quoted_amount=500 and customer_label='Cliente Test Demo' from public.reservations where id=res);
 perform public.manager_gateway(token,'rate.save',club,jsonb_build_object('id',peak,'alias','TEST peak','amount',300,'currency','CLP','is_active',true,'is_default',false));
 assert(select quoted_amount=500 from public.reservations where id=res);
 log:=log||'"historical quote remains after price edit"'::jsonb;
 begin perform public.manager_gateway(token,'reservation.create',club,jsonb_build_object('court_id',court,'start_local',dt||'T18:00','minutes',30));raise exception 'Overlap accepted';exception when exclusion_violation then null;end;
 begin perform public.manager_gateway(token,'block.save',club,jsonb_build_object('court_id',court,'start_local',dt||'T18:00','end_local',dt||'T19:00','reason','TEST'));raise exception 'Conflict accepted';exception when exclusion_violation then null;end;
 log:=log||'"reservation overlap and contradictory block denied"'::jsonb;
 perform public.manager_gateway(token,'reservation.cancel',club,jsonb_build_object('id',res));
 out:=public.manager_gateway(token,'block.save',club,jsonb_build_object('court_id',court,'start_local',dt||'T18:00','end_local',dt||'T19:00','reason','TEST'));blk:=(out->>'id')::uuid;
 assert exists(select 1 from jsonb_array_elements(private.calendar(club,dt))x where x->>'court_id'=court::text and x->>'state'='BLOCKED');
 log:=log||'"block persists and calendar marks it"'::jsonb;
 perform public.manager_gateway(token,'block.save',club,jsonb_build_object('id',blk,'court_id',court,'start_local',dt||'T19:00','end_local',dt||'T20:00','reason','EDITED TEST'));
 perform public.manager_gateway(token,'block.delete',club,jsonb_build_object('id',blk));
 log:=log||'"edit and remove block"'::jsonb;
 out:=public.manager_gateway(token,'rate.save',club,jsonb_build_object('alias','TEST promo','amount',50,'currency','CLP','is_active',true,'is_default',false));promo:=(out->>'id')::uuid;
 perform public.manager_gateway(token,'override.save',club,jsonb_build_object('court_ids',jsonb_build_array(court),'rate_plan_id',promo,'date_from',dt,'date_to',dt,'days',jsonb_build_array(day_no),'start_min',1080,'end_min',1200,'priority',999));
 q:=private.quote_court(court,st,90);assert(q->>'amount')::numeric=200;
 log:=log||'"dated promotion overrides schedule and default"'::jsonb;
 out:=public.manager_gateway(token,'court.save',club,'{"name":"TEST destination","court_number":902,"status":"ACTIVE"}');dest:=(out->>'id')::uuid;
 perform public.manager_gateway(token,'schedule.copy',club,jsonb_build_object('court_id',court,'court_ids',jsonb_build_array(dest)));
 assert(select count(*)=1 from public.court_rate_schedules where court_id=dest);
 log:=log||'"copy rates between courts"'::jsonb;
 perform public.manager_gateway(token,'schedule.copy_day',club,jsonb_build_object('court_id',dest,'source_day',day_no,'days',jsonb_build_array((day_no+1)%7)));
 assert(select count(*)=2 from public.court_rate_schedules where court_id=dest);
 log:=log||'"copy rates between days"'::jsonb;
 out:=public.manager_gateway(token,'snapshot',club,jsonb_build_object('date',dt));
 assert exists(select 1 from jsonb_array_elements(out->'reservations') r where r->>'id'=res::text and r->>'customer_label'='Cliente Test Demo');
 log:=log||'"reservation detail and payment absence"'::jsonb;
 begin perform public.manager_gateway(token,'schedule.apply',other_club,jsonb_build_object('court_ids',jsonb_build_array(dest),'days',jsonb_build_array(0),'start_min',480,'end_min',600,'rate_plan_id',rate));raise exception 'Cross-club rate accepted';exception when others then if sqlerrm='Cross-club rate accepted' then raise;end if;end;
 log:=log||'"cross-club assignment rejected"'::jsonb;
 perform public.manager_gateway(token,'court.delete',club,jsonb_build_object('court_id',court));
 assert(select status='INACTIVE' from public.courts where id=court);
 perform public.manager_gateway(token,'court.delete',club,jsonb_build_object('court_id',dest));
 assert not exists(select 1 from public.courts where id=dest);
 log:=log||'"logical deletion with history and physical deletion without history"'::jsonb;
 update public.clubs set is_demo=false where id=club;
 begin perform public.manager_gateway(token,'rate.save',club,'{}');raise exception 'Production write accepted';exception when insufficient_privilege then null;end;
 log:=log||'"non-demo administrative write rejected"'::jsonb;
 assert not has_table_privilege('anon','public.rate_plans','INSERT');
 assert not has_table_privilege('anon','public.court_operating_windows','INSERT');
 log:=log||'"no anonymous direct administrative table writes"'::jsonb;
 raise exception using errcode='P9999',message='rollback all test data';
 exception when sqlstate 'P9999' then null;
 end;
 insert into manager_test_result values(log);
end $$;
select report,jsonb_array_length(report) as passed from manager_test_result;
